# shellcheck disable=SC2034  # the L_* locations are read through po_expand
po_init_locations() {
    if [ -n "${HOME:-}" ]; then L_HOME="${HOME}"
    else po_die "cannot resolve the HOME location"; fi
    if [ -n "${XDG_DATA_HOME:-}" ]; then L_DATA_HOME="${XDG_DATA_HOME}/prompt-orchestrator"
    elif true; then L_DATA_HOME="$(po_expand '{HOME}/.local/share/prompt-orchestrator')"
    else po_die "cannot resolve the DATA_HOME location"; fi
    if [ -n "${CODEX_HOME:-}" ]; then L_CODEX_HOME="${CODEX_HOME}"
    elif true; then L_CODEX_HOME="$(po_expand '{HOME}/.codex')"
    else po_die "cannot resolve the CODEX_HOME location"; fi
    if true; then L_OPENCODE="$(po_expand '{HOME}/.config/opencode')"
    else po_die "cannot resolve the OPENCODE location"; fi
}

po_tool_label() {
    case "$1" in
        'claude') printf '%s' 'Claude Code' ;;
        'codex') printf '%s' 'OpenAI Codex' ;;
        'opencode') printf '%s' 'OpenCode' ;;
        'cursor') printf '%s' 'Cursor' ;;
        'gemini') printf '%s' 'Gemini CLI' ;;
        'antigravity') printf '%s' 'Antigravity' ;;
        'openclaw') printf '%s' 'OpenClaw' ;;
        'copilot') printf '%s' 'GitHub Copilot (harness agents only)' ;;
        'kiro') printf '%s' 'Kiro (harness agents only)' ;;
        *) printf '' ;;
