PO_EOF
            ;;
        'codex') cat <<'PO_EOF'
tree	.agents/skills	{HOME}/.agents/skills
tree	.codex/prompts	{CODEX_HOME}/prompts
doc	AGENTS.md	{CODEX_HOME}/AGENTS.md
PO_EOF
            ;;
        'opencode') cat <<'PO_EOF'
tree	.opencode/skills	{OPENCODE}/skills
tree	.opencode/commands	{OPENCODE}/commands
doc	AGENTS.md	{OPENCODE}/AGENTS.md
PO_EOF
            ;;
        'cursor') cat <<'PO_EOF'
