doc	AGENTS.md	{HOME}/.cursor/AGENTS.md
PO_EOF
            ;;
        'gemini') cat <<'PO_EOF'
tree	.gemini/commands	{HOME}/.gemini/commands
tree	.agents/skills	{HOME}/.agents/skills
doc	AGENT.md	{HOME}/.gemini/GEMINI.md
PO_EOF
            ;;
        'antigravity') cat <<'PO_EOF'
