tree	skills	{HOME}/.openclaw/skills
tree	workflows	{HOME}/.openclaw/workflows
tree	.agents/skills	{HOME}/.openclaw/agents-skills
PO_EOF
            ;;
        *) printf '' ;;
    esac
}
